import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaUserCircle, FaLock, FaPlay, FaChartLine, FaSignOutAlt, FaHome } from 'react-icons/fa';
import { toast } from 'react-toastify';
import { useAuth } from '../../../context/AuthContext';
import { useProgress } from '../../../context/ProgressContext';
import enrollmentService from '../../../services/enrollmentService';
import courseService from '../../../services/courseService';
import videoService from '../../../services/videoService';
import Spinner from '../../../components/Spinner';
import EnrollmentRequest from '../../Auth/EnrollmentRequest';
import '../../../styles/StudentDashboard.css';
import '../../../App.css';

const StudentDashboard = () => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();
  const { isUnlocked, completedVideos } = useProgress();

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showProgress, setShowProgress] = useState(false);
  const [showEnrollmentRequest, setShowEnrollmentRequest] = useState(false);
  const [selectedSubject, setSelectedSubject] = useState("All");

  const [loading, setLoading] = useState(true);
  const [enrollments, setEnrollments] = useState([]);
  const [videos, setVideos] = useState([]);
  const [currentCourse, setCurrentCourse] = useState(null);

  // Fetch enrollments and videos on mount
  useEffect(() => {
    const fetchStudentData = async () => {
      try {
        setLoading(true);

        // Fetch student's enrollments
        const enrollmentData = await enrollmentService.getMyEnrollments();
        setEnrollments(enrollmentData);

        if (enrollmentData && enrollmentData.length > 0) {
          // Get the first enrolled course
          const firstEnrollment = enrollmentData[0];
          setCurrentCourse(firstEnrollment.course);

          // Fetch videos for the enrolled course
          if (firstEnrollment.course?._id) {
            try {
              const videoData = await videoService.getCourseVideos(firstEnrollment.course._id);
              setVideos(videoData || []);
            } catch (error) {
              console.log('No videos found for course, using empty array');
              setVideos([]);
            }
          }
        }
      } catch (error) {
        console.error('Error fetching student data:', error);
        // Fallback to localStorage for backward compatibility
        const savedCourse = localStorage.getItem('selectedCourse') || "B.Sc Information Technology";
        setCurrentCourse({ title: savedCourse });
        toast.warning('Using offline mode. Some features may be limited.');
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchStudentData();
    }
  }, [user]);

  // Unique Subjects for filtering
  const subjects = ["All", ...new Set(videos.map(v => v.subject?.name || v.subject).filter(Boolean))];

  // Filtered Videos
  const filteredVideos = selectedSubject === "All"
    ? videos
    : videos.filter(v => (v.subject?.name || v.subject) === selectedSubject);

  // Progress Calculations (always based on total available)
  const totalVideos = videos.length;
  const completedCount = videos.filter(v => completedVideos.includes(v._id || v.id)).length;
  const progressPercentage = totalVideos > 0 ? Math.round((completedCount / totalVideos) * 100) : 0;

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  // Check if user has pending enrollments
  const hasPendingEnrollment = enrollments.some(e => e.status === 'pending');
  const isApproved = enrollments.some(e => e.status === 'approved');

  if (loading) {
    return <Spinner message="Loading your dashboard..." />;
  }

  // Approval Guard - Show if no approved enrollments
  if (!isApproved && hasPendingEnrollment) {
    return (
      <div className="dashboard-container" style={{ justifyContent: 'center', alignItems: 'center', background: '#FFFDD0' }}>
        <div className="card" style={{ maxWidth: '500px', textAlign: 'center', padding: '40px', background: 'white', borderRadius: '15px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
          <div style={{ background: '#fef3c7', width: '80px', height: '80px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifySelf: 'center', justifyContent: 'center', margin: '0 auto 20px auto' }}>
            <FaLock size={40} color="#d97706" />
          </div>
          <h1 style={{ color: '#006D5B', marginBottom: '15px' }}>Account Pending Approval</h1>
          <p style={{ color: '#666', fontSize: '1.1rem', lineHeight: '1.6', marginBottom: '25px' }}>
            Hello <strong>{user?.name}</strong>! Your enrollment request has been sent to the teacher.
          </p>
          <div style={{ background: '#f0fdf4', padding: '15px', borderRadius: '8px', border: '1px solid #c6f6d5', color: '#166534', fontSize: '0.9rem', marginBottom: '30px' }}>
            Please wait for the teacher to verify your enrollment. You will gain access to videos and quizzes once approved.
          </div>
          <button onClick={handleLogout} className="btn btn-primary" style={{ width: '100%' }}>
            <FaSignOutAlt /> Log Out
          </button>
        </div>
      </div>
    );
  }

  // If no enrollments at all, prompt to enroll
  if (enrollments.length === 0) {
    return (
      <div className="dashboard-container" style={{ justifyContent: 'center', alignItems: 'center', background: '#FFFDD0' }}>
        <div className="card" style={{ maxWidth: '500px', textAlign: 'center', padding: '40px', background: 'white', borderRadius: '15px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
          <h1 style={{ color: '#006D5B', marginBottom: '15px' }}>Welcome, {user?.name}!</h1>
          <p style={{ color: '#666', fontSize: '1.1rem', lineHeight: '1.6', marginBottom: '25px' }}>
            You haven't enrolled in any courses yet.
          </p>
          <div style={{ background: '#f0fdf4', padding: '15px', borderRadius: '8px', border: '1px solid #c6f6d5', color: '#166534', fontSize: '0.9rem', marginBottom: '30px' }}>
            Please contact your administrator to enroll in a course.
          </div>
          <button onClick={handleLogout} className="btn btn-primary" style={{ width: '100%' }}>
            <FaSignOutAlt /> Log Out
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      {/* Progress Tracker Modal (Unchanged) */}
      {showProgress && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h2>Learning Statistics</h2>
              <button onClick={() => setShowProgress(false)} className="close-btn">&times;</button>
            </div>

            <div style={{ textAlign: 'center', padding: '20px 0' }}>
              <div className="progress-circle">
                <span className="progress-text">{progressPercentage}%</span>
              </div>
              <h3 style={{ marginTop: '20px', color: '#006D5B' }}>
                {completedCount} / {totalVideos} Modules Completed
              </h3>
              <div className="progress-bar-bg">
                <div className="progress-bar-fill" style={{ width: `${progressPercentage}%` }}></div>
              </div>
              <p style={{ color: '#666', marginTop: '15px' }}>
                {progressPercentage === 100
                  ? "Congratulations! You've completed all modules!"
                  : "Keep going! You're doing great."}
              </p>
            </div>

            <button onClick={() => setShowProgress(false)} className="modal-close-btn">Close</button>
          </div>
        </div>
      )}

      {/* Sidebar (Unchanged) */}
      <div
        className="sidebar"
        style={{ width: isSidebarOpen ? '250px' : '70px' }}
        onMouseEnter={() => setIsSidebarOpen(true)}
        onMouseLeave={() => setIsSidebarOpen(false)}
      >
        <button
          className="profile-button"
          onClick={() => navigate('/student/profile')}
          title="View Profile"
        >
          {user?.photo ? (
            <img src={user.photo} alt="Profile" className="sidebar-profile-img" />
          ) : (
            <FaUserCircle size={40} color="#FFFDD0" />
          )}
          {isSidebarOpen && <span className="username">{user?.name}</span>}
        </button>

        <div className="nav-items">
          <div className="nav-item">
            <FaHome size={24} className="nav-icon" />
            {isSidebarOpen && <span>Dashboard</span>}
          </div>
          <div className="nav-item" onClick={() => setShowProgress(true)}>
            <FaChartLine size={24} className="nav-icon" />
            {isSidebarOpen && <span>Statistics</span>}
          </div>
        </div>

        <div className="logout-section" onClick={handleLogout}>
          <FaSignOutAlt size={24} className="nav-icon" />
          {isSidebarOpen && <span>Logout</span>}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="content-area">
        <div className="dashboard-header-modern">
          <div className="course-banner">
            <span className="course-label">Enrolled Course</span>
            <h1 className="course-name">{currentCourse?.title || currentCourse?.name || 'My Course'}</h1>
          </div>

          <div className="subject-selector">
            <span className="subject-label">Filter by Subject:</span>
            <div className="subject-tabs">
              {subjects.map(subject => (
                <button
                  key={subject}
                  className={`subject-tab ${selectedSubject === subject ? 'active' : ''}`}
                  onClick={() => setSelectedSubject(subject)}
                >
                  {subject}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="grid">
          {filteredVideos.length === 0 ? (
            <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '60px 20px' }}>
              <p style={{ fontSize: '1.2rem', color: '#666' }}>
                No videos available yet. Check back later!
              </p>
            </div>
          ) : (
            filteredVideos.map((video) => {
              const videoId = video._id || video.id;
              const isLocked = !isUnlocked(videoId);
              return (
                <div key={videoId} className="card-custom">
                  {/* Thumbnail */}
                  <div className="thumbnail">
                    {isLocked ? (
                      <div className="text-center">
                        <FaLock size={30} style={{ marginBottom: '10px' }} />
                        <p>Locked</p>
                      </div>
                    ) : (
                      <Link to={`/video/${videoId}`} style={{ color: 'white' }}>
                        <FaPlay size={40} />
                      </Link>
                    )}
                    <span className="subject-badge">{video.subject?.name || video.subject}</span>
                  </div>

                  {/* Content */}
                  <div className="card-content" style={{ padding: '20px' }}>
                    <h3 className="card-title">{video.title}</h3>
                    <p className="card-desc">{video.description}</p>

                    {isLocked ? (
                      <button className="disabled-btn" disabled>Complete Previous Task</button>
                    ) : (
                      <Link to={`/video/${videoId}`}>
                        <button className="start-btn">Start Module</button>
                      </Link>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;
